const payload = items[0]?.json ?? {};
const execution = payload.execution ?? {};
const workflow = payload.workflow ?? {};
const error = payload.error ?? payload;

const parseLeadId = () => {
  const candidates = [
    payload.lead_id,
    payload.leadId,
    execution?.data?.resultData?.lastNodeExecutedData?.lead_id,
    execution?.data?.lead_id,
    error?.lead_id,
  ];

  for (const value of candidates) {
    if (value === undefined || value === null || value === '') continue;
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return numeric;
  }

  return null;
};

const leadId = parseLeadId();
const workflowName = workflow.name || execution.workflowData?.name || 'unknown_workflow';
const message = error.message || error.description || 'Unhandled n8n workflow error';
const stack = error.stack || null;
const lastNode = execution.lastNodeExecuted || execution.data?.resultData?.lastNodeExecuted || null;

return [
  {
    json: {
      lead_id: leadId,
      event_name: 'workflow_execution_error',
      entity_type: leadId ? 'lead' : 'workflow',
      entity_id: leadId,
      result: 'error',
      before_payload_json: JSON.stringify({ workflow_name: workflowName, last_node: lastNode }),
      after_payload_json: JSON.stringify({ message, stack }),
      metadata_json: JSON.stringify({
        workflow_name: workflowName,
        workflow_id: workflow.id || execution.workflowId || null,
        last_node: lastNode,
        execution_status: execution.status || null,
      }),
    },
  },
];
